1	import { getJson, postJson } from '../../api/http';
2	
3	// A project's invoices under a per-project key: anything showing project 1's invoices reads
4	// ['invoices', 1], and a write invalidates the same key to refresh them (CLAUDE.md rule 5). An
5	// invoice carries its own id, its project's id and a monetary amount.
6	export type Invoice = {
7	  id: number;
8	  projectId: number;
9	  amount: number;
10	  status: string;
11	  issuedDate: string;
12	  dueDate: string;
13	  /** How much has been settled against this invoice so far (sum of its payments). */
14	  paid: number;
15	  /** How much is still owed after payments: amount - paid. Derived server-side. */
16	  due: number;
17	};
18	
19	export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;
20	
21	// Every invoice across all projects, each carrying the NAME of its project (the cross-entity join
22	// is done server-side, in AllInvoicesGet). Read under ['invoices', 'all'] (CLAUDE.md rule 5).
23	export type AllInvoice = {
24	  id: number;
25	  projectId: number;
26	  projectName: string;
27	  amount: number;
28	  status: string;
29	};
30	
31	export const allInvoicesKey = ['invoices', 'all'] as const;
32	
33	export function fetchAllInvoices(): Promise<AllInvoice[]> {
34	  return getJson<AllInvoice[]>('/api/invoices');
35	}
36	
37	/** URL key owned by the sort control; readers (the list) sort by the same key (CLAUDE.md rule 4). */
38	export const INVOICE_SORT_PARAM = 'invoiceSort';
39	
40	/** URL key owned by the stage filter; the all-invoices list narrows to this stage (CLAUDE.md rule 4). */
