package net.officefloor.hq.app;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A client the user keeps track of: a name and an email. Persisted to the {@code clients} table
 * (Flyway V1). Jackson serialises the getters as the JSON the front-end reads.
 */
@Entity
@Table(name = "clients")
public class Client {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    private String email;

    private boolean archived;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public boolean isArchived() {
        return archived;
    }

    public void setArchived(boolean archived) {
        this.archived = archived;
    }
}

package net.officefloor.hq.app;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

/**
 * Data access for {@link Client}. A Spring Data bean, injected into the OfficeFloor logic classes
 * (Spring beans are exposed to OfficeFloor by the rest-spring-boot starter).
 */
public interface ClientRepository extends JpaRepository<Client, Long> {

    List<Client> findAllByOrderByIdAsc();

    /**
     * Every client that has not been tucked away, oldest id first — archived clients are excluded so
     * a tucked-away client drops off the list (and its search, which filters this same list).
     */
    List<Client> findAllByArchivedFalseOrderByIdAsc();

    /**
     * Every client that has been tucked away, oldest id first — the archived clients, so a "show
     * archived" view can list them and bring one back.
     */
    List<Client> findAllByArchivedTrueOrderByIdAsc();

    /** Whether a client already uses this email — no two clients may share one. */
    boolean existsByEmail(String email);

    /**
     * Whether a client OTHER than the one with {@code id} already uses this email — the uniqueness
     * check for an edit, so a client may keep its own address without tripping the duplicate rule.
     */
    boolean existsByEmailAndIdNot(String email, Long id);
}

